CREATE TABLE public.stg_whitney_kona_biopsies ("row_no" text, "psn_id" text, "sample_id" text, "pop" text, "sample_number" text, "date_biopsy_raw" text, "manta_name" text, "mprf_id_raw" text, "sex" text, "sighting_location" text, "biopsy_location" text, "video_pics" text, "idd_by" text, "sampled_by" text, "biopsy_name" text, "hamr_id_raw" text, "vial_id" text, "size_at_biopsy_m_raw" text, "age_class_at_biopsy" text, "date_first_sighting_raw" text, "size_first_sighting_m_raw" text);
GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.stg_whitney_kona_biopsies TO authenticated,service_role;
CREATE VIEW fixture_structure AS SELECT c.oid,c.relname,c.relowner,c.relrowsecurity,c.relforcerowsecurity,
(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0) columns,
(SELECT jsonb_agg(pg_get_constraintdef(oid) ORDER BY conname) FROM pg_constraint WHERE conrelid=c.oid) constraints,
(SELECT jsonb_agg(pg_get_triggerdef(oid) ORDER BY tgname) FROM pg_trigger WHERE tgrelid=c.oid) triggers
FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind='r';
CREATE TEMP TABLE structure_before AS SELECT * FROM fixture_structure;
CREATE TEMP TABLE acl_before AS SELECT c.oid,(SELECT jsonb_agg(to_jsonb(a) ORDER BY grantor,grantee,privilege_type) FROM aclexplode(c.relacl) a) acl FROM pg_class c JOIN structure_before b USING(oid);
